						var at     = 0;

						if (expected != null)
						{
							expected.CopyTo(merged, 0);
							at = expected.Length;
						}

						foreach (var each in _tied)
						{
							each.CopyTo(merged, at);
							at += each.Length;
						}

						expected = merged;
